<script setup lang="ts">
import { computed, onMounted, ref, useSlots } from 'vue';
const slots = useSlots();
const mounted = ref(false);
onMounted(() => { mounted.value = true; });
import { namespaceContext, namespaceContextOptions, setNamespaceContext } from '../data/namespace-context';
import MultiFilter from './MultiFilter.vue';
type Option = { value: string; label: string };
const props = withDefaults(defineProps<{ search: string; namespace?: string; grouped?: boolean; namespaces: string[]; searchLabel: string; placeholder?: string; extraColumns?: string[]; multiNamespace?: boolean; namespaceSelection?: string[]; showGrouping?: boolean; showProtocols?: boolean; protocolOptions?: Option[]; protocolSelection?: string[]; showServicePorts?: boolean; servicePortOptions?: Option[]; servicePortSelection?: string[] }>(), { namespace: '__all__', grouped: false, multiNamespace: false, showGrouping: true, showProtocols: false, showServicePorts: false, namespaceSelection: () => [], protocolOptions: () => [], protocolSelection: () => [], servicePortOptions: () => [], servicePortSelection: () => [] });
const emit = defineEmits<{ 'update:search': [value: string]; 'update:namespace': [value: string]; 'update:grouped': [value: boolean]; 'update:namespaceSelection': [value: string[]]; 'update:protocolSelection': [value: string[]]; 'update:servicePortSelection': [value: string[]] }>();
const columns = computed(() => ['minmax(200px,1fr)', '220px', ...(props.showGrouping ? ['160px'] : []), ...(props.showProtocols ? ['170px'] : []), ...(props.showServicePorts ? ['170px'] : []), ...(slots.extra ? props.extraColumns || ['200px'] : [])].join(' '));
</script>
<template>
  <Teleport v-if="mounted" to="#snm-inventory-filters"><div class="inventory-filters" :style="{ '--filter-columns': columns }"><label class="filter-search">{{ searchLabel }}<input type="search" :value="search" :placeholder="placeholder || 'Name or namespace…'" @input="emit('update:search', ($event.target as HTMLInputElement).value)"></label><MultiFilter label="Namespaces" :model-value="namespaceContext" :options="namespaceContextOptions" @update:model-value="setNamespaceContext($event); emit('update:namespace', '__all__'); emit('update:namespaceSelection', [])" /><label v-if="showGrouping">Group By<select :value="grouped ? 'namespace' : ''" @change="emit('update:grouped', ($event.target as HTMLSelectElement).value === 'namespace')"><option value=""></option><option value="namespace">Namespace</option></select></label><MultiFilter v-if="showProtocols" label="Protocols" :model-value="protocolSelection" :options="protocolOptions" @update:model-value="emit('update:protocolSelection', $event)" /><MultiFilter v-if="showServicePorts" label="Service & Ports" :model-value="servicePortSelection" :options="servicePortOptions" @update:model-value="emit('update:servicePortSelection', $event)" /><slot name="extra" /></div><slot name="secondary" /></Teleport>
</template>
<style scoped>
.inventory-filters { display:grid; grid-template-columns:var(--filter-columns); gap:18px; align-items:end; margin:22px 0 20px; }.inventory-filters label { display:flex; flex-direction:column; gap:8px; font-size:12px; color:var(--muted,#a5b1c3); min-width:0; }.inventory-filters :deep(input:not([type="checkbox"])),.inventory-filters :deep(select) { width:100%; box-sizing:border-box; min-height:42px; padding:10px; font:inherit; color:var(--body-text,#dce3ed); background:var(--input-bg,#1c2430); border:1px solid var(--border,#384352); border-radius:5px; }.inventory-filters input:focus-visible,.inventory-filters select:focus-visible { outline:2px solid #73b5ff; outline-offset:3px; }.inventory-filters :deep(.multi-filter) { min-width:0; }.inventory-filters :deep(.multi-filter > span) { margin-bottom:8px; }.inventory-filters :deep(.multi-filter summary) { box-sizing:border-box; min-height:42px; display:flex; align-items:center; padding:10px; }.inventory-filters :deep(.multi-filter summary::before) { content:'▸'; margin-right:5px; }.inventory-filters :deep(.multi-filter details[open] summary::before) { content:'▾'; }@media(max-width:800px) { .inventory-filters { grid-template-columns:1fr; } }
</style>
